const body = $input.first().json.body ?? {};
const UNITS = ['piece', 'ml', 'gram'];
const TIMES = ['quick', 'medium', 'complex'];
const CUISINES = ['german', 'italian', 'indian', 'japanese', 'gourmet', 'fusion'];
const DIETS = ['vegetarian', 'vegan', 'keto', 'none'];
const NAME = /^[\p{L} -]{1,50}$/u;
const errors = [];
const inRange = (v, min, max) => Number.isInteger(v) && v >= min && v <= max;

const list = Array.isArray(body.ingredients) ? body.ingredients : [];
if (list.length < 1 || list.length > 30) errors.push('ingredients: 1 to 30 entries required');

const seen = new Set();
list.forEach((item, n) => {
  const name = typeof item?.name === 'string' ? item.name.trim() : '';
  if (!NAME.test(name) || !/\p{L}/u.test(name)) errors.push(`ingredients[${n}].name invalid`);
  if (seen.has(name.toLowerCase())) errors.push(`ingredients[${n}].name duplicate`);
  seen.add(name.toLowerCase());
  if (typeof item?.amount !== 'number' || !(item.amount > 0) || item.amount > 100000) {
    errors.push(`ingredients[${n}].amount invalid`);
  }
  if (!UNITS.includes(item?.unit)) errors.push(`ingredients[${n}].unit invalid`);
});

if (!inRange(body.portions, 1, 12)) errors.push('portions: integer 1-12');
if (!inRange(body.helpers, 1, 4)) errors.push('helpers: integer 1-4');
if (!TIMES.includes(body.time)) errors.push('time invalid');
if (!CUISINES.includes(body.cuisine)) errors.push('cuisine invalid');
if (!DIETS.includes(body.diet)) errors.push('diet invalid');

const okLang = /^[a-z]{2,3}(-[A-Za-z]{2,4})?$/.test(body.language ?? '');
const data = {
  ingredients: list.map((i) => ({ name: String(i?.name ?? '').trim(), amount: i?.amount, unit: i?.unit })),
  portions: body.portions,
  helpers: body.helpers,
  time: body.time,
  cuisine: body.cuisine,
  diet: body.diet,
  language: okLang ? body.language : 'en',
};

return [{ json: { valid: errors.length === 0, errors, data } }];

const input = $('Validate input').first().json.data;
const out = $input.first().json;
let raw = out.content?.parts?.[0]?.text
  ?? out.candidates?.[0]?.content?.parts?.[0]?.text
  ?? out.text ?? out.output ?? out;
if (typeof raw === 'string') raw = raw.replace(/```json|```/g, '').trim();
const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
const recipes = parsed.recipes;

if (!Array.isArray(recipes) || recipes.length !== 3) throw new Error('Gemini did not return exactly 3 recipes');

const wanted = input.ingredients.map((i) => i.name.toLowerCase());
const need = Math.ceil(wanted.length * 0.7);
recipes.forEach((r, n) => {
  const used = (r.used_ingredients ?? []).map((i) => String(i.name).toLowerCase());
  const hits = wanted.filter((w) => used.some((u) => u.includes(w) || w.includes(u))).length;
  if (hits < need) throw new Error(`Recipe ${n + 1} uses too few ingredients`);
  if ((r.extra_ingredients ?? []).length > 3) throw new Error(`Recipe ${n + 1} has too many extras`);
  if (!r.title || !Array.isArray(r.steps) || !r.nutrition) throw new Error(`Recipe ${n + 1} incomplete`);
});

return recipes.map((r) => ({ json: { ...r, request: input } }));

const batchId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = (Math.random() * 16) | 0;
  return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
});
return $input.all().map(({ json: r }) => ({
  json: {
    batch_id: batchId,
    title: r.title,
    cooking_time_min: r.cooking_time_min,
    time_category: r.request.time,
    cuisine: r.request.cuisine,
    diet: r.request.diet,
    portions: r.request.portions,
    helpers: r.request.helpers,
    language: r.request.language,
    used_ingredients: r.used_ingredients,
    extra_ingredients: r.extra_ingredients,
    steps: r.steps,
    nutrition: r.nutrition,
  },
}));

const headers = $input.first().json.headers ?? {};
const forwarded = String(headers['x-forwarded-for'] ?? '').split(',')[0].trim();
const ip = forwarded || String(headers['x-real-ip'] ?? '').trim() || 'unknown';
const valid = /^[0-9a-fA-F:.]{3,45}$/.test(ip);
return [{ json: { ...$input.first().json, client_ip: valid ? ip : 'unknown' } }];
